1	const express = require('express');
2	const router = express.Router();
3	const { DetectionAlert, IncidentLog, MonitoringZone, Camera, sequelize } = require('../models');
4	const { resolveIncidentType } = require('../utils/detectionAlertBridge');
5	function severityFromDuration(seconds) {
6	  if (!seconds || seconds < 120) return 'Low';
7	  if (seconds < 300) return 'Medium';
8	  if (seconds < 600) return 'High';
9	  return 'Critical';
10	}
11	const { Op } = require('sequelize');
12	const { verifyToken, requireRole, verifyServiceOrRole } = require('../middlewares/auth');
13	const SEVERITIES = ['Low', 'Medium', 'High', 'Critical'];
14	const VALID_STATUSES = ['Active', 'Acknowledged', 'Investigating', 'Dispatched', 'Escalated', 'Cleared'];
15	
16	// This route is reachable by the AI engine's service key AND by an FM/Staff JWT — never
17	// by the SecurePi edge device (that's the dedicated EDGE_INGEST_TOKEN route in
18	// edgeDetectionAlerts.js). Whitelisting here stops either caller from setting
19	// source: 'SecurePi Edge Node' and having an alert masquerade as edge-ingested.
20	const ALLOWED_ALERT_SOURCES = ['Browser Webcam', 'Uploaded Video', 'Object Detection'];
21	const DEFAULT_ALERT_SOURCE = 'Object Detection';
22	
23	function resolveAlertSource(rawSource, maxLength) {
24	    const cleaned = cleanText(rawSource, maxLength);
25	    return (cleaned && ALLOWED_ALERT_SOURCES.includes(cleaned)) ? cleaned : DEFAULT_ALERT_SOURCE;
26	}
27	
28	// Maps a DetectionAlert workflow status onto the IncidentLog resolutionStatus values the
29	// Incident Dashboard already understands (Active / Investigating / Escalated to Security / Cleared).
30	const STATUS_TO_RESOLUTION = {
31	    Active: 'Active',
32	    Acknowledged: 'Active',
33	    Investigating: 'Investigating',
34	    Dispatched: 'Investigating',
35	    Escalated: 'Escalated to Security',
36	    Cleared: 'Cleared'
37	};
38	
39	// Runs fn inside a managed transaction when the connection is available; unit tests that
40	// mock ../models without a sequelize instance fall back to running fn untransacted.
41	const withTransaction = (fn) => {
42	    if (sequelize && typeof sequelize.transaction === 'function') {
43	        return sequelize.transaction(fn);
44	    }
45	    return fn(null);
46	};
47	
48	const cleanText = (value, maxLength) => {
49	    if (value === undefined || value === null) return null;
50	    const text = String(value).trim();
51	    if (!text) return null;
52	    return text.slice(0, maxLength);
53	};
54	
55	const parsePositiveInt = (value) => {
56	    if (value === undefined || value === null || value === '') return null;
57	    const parsed = parseInt(value, 10);
58	    return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
59	};
60	
61	const parseConfidence = (value) => {
62	    if (value === undefined || value === null || value === '') return null;
63	    const parsed = Number(value);
64	    if (!Number.isFinite(parsed)) return null;
65	    return Math.max(0, Math.min(1, parsed));
66	};
67	
68	const parseOccurredAt = (value) => {
69	    if (!value) return null;
70	    const date = new Date(value);
71	    return Number.isNaN(date.getTime()) ? null : date;
72	};
73	
74	router.get('/', verifyToken, requireRole('FM', 'Staff'), async (req, res) => {
75	    try {
76	        const where = {};
77	        if (req.query.status) where.status = req.query.status;
78	        const alerts = await DetectionAlert.findAll({
79	            where,
80	            order: [['createdAt', 'DESC']],
81	            limit: 50
82	        });
83	        res.json(alerts);
84	    } catch (err) {
85	        res.status(500).json({ error: err.message });
86	    }
87	});
88	
89	router.get('/:id', verifyToken, requireRole('FM', 'Staff'), async (req, res) => {
90	    try {
91	        // Non-numeric ids would make Postgres throw on an integer PK lookup — treat as not found.
92	        if (!/^\d+$/.test(req.params.id)) return res.sendStatus(404);
93	        const alert = await DetectionAlert.findByPk(req.params.id);
94	        if (!alert) return res.sendStatus(404);
95	        res.json(alert);
96	    } catch (err) {
97	        res.status(500).json({ error: err.message });
98	    }
99	});
100	
101	// Resolves best-effort zone_id/camera_id from the free-text zone_name/camera_location the
102	// AI engine (or a manual caller) sends — additive enrichment, never blocks alert creation.
103	// Also surfaces the zone's Detection Setup detection_type (a separate `detectionType`
104	// key, NOT spread into DetectionAlert.create — that model has no such column) so the
105	// incident-type bridge below can use it without a second DB round trip.
106	async function resolveLinks(zone_name, camera_location) {
107	    const links = {};
108	    let detectionType = null;
109	    try {
110	        if (zone_name) {
111	            const zone = await MonitoringZone.findOne({ where: { zone_name } });
112	            if (zone) {
113	                links.zone_id = zone.id;
114	                detectionType = zone.detection_type || null;
115	            }
116	        }
117	        if (camera_location) {
118	            const camera = await Camera.findOne({
119	                where: {
120	                    [Op.or]: [{ camera_name: camera_location }, { location: camera_location }]
121	                }
122	            });
123	            if (camera) links.camera_id = camera.id;
124	        }
125	    } catch {
126	        // Enrichment is best-effort only — never fail alert creation because of it.
127	    }
128	    return { links, detectionType };
129	}
130	
131	// AI engine posts here server-to-server via a shared service key; FM/Staff may also
132	// create a manual test alert using their own JWT.
133	router.post('/', verifyServiceOrRole('FM', 'Staff'), async (req, res) => {
134	    try {
135	        const {
136	            zone_name,
137	            camera_location,
138	            status,
139	            object_class,
140	            duration_seconds,
141	            person_name,
142	            alert_type,
143	            severity,
144	            source,
145	            confidence,
146	            snapshot_url,
147	            snapshot_path,
148	            device_id,
149	            timestamp,
150	            occurred_at
151	        } = req.body;
152	        if (!zone_name || !camera_location) {
153	            return res.status(400).json({ error: 'zone_name and camera_location are required.' });
154	        }
155	        if (status && !VALID_STATUSES.includes(status)) {
156	            return res.status(400).json({ error: `status must be one of: ${VALID_STATUSES.join(', ')}.` });
157	        }
158	        if (severity && !SEVERITIES.includes(severity)) {
159	            return res.status(400).json({ error: `severity must be one of: ${SEVERITIES.join(', ')}.` });
160	        }
161	        const { links, detectionType } = await resolveLinks(zone_name, camera_location);
162	        const resolvedSeverity = severity || severityFromDuration(duration_seconds);
163	        const cleanedAlertType = cleanText(alert_type, 100);
164	        const cleanedObjectClass = cleanText(object_class, 100);
165	        const resolvedSource = resolveAlertSource(source, 100);
166	        const incidentType = resolveIncidentType({
167	            alert_type: cleanedAlertType,
168	            object_class: cleanedObjectClass,
169	            detection_type: detectionType
170	        });
171	
172	        // Alert + linked incident are created atomically: if either fails, neither persists.
173	        const alert = await withTransaction(async (t) => {
174	            const created = await DetectionAlert.create({
175	                zone_name: cleanText(zone_name, 255),
176	                camera_location: cleanText(camera_location, 255),
177	                status: status || 'Active',
178	                object_class: cleanedObjectClass,
179	                duration_seconds: parsePositiveInt(duration_seconds),
180	                person_name: cleanText(person_name, 255),
181	                alert_type: cleanedAlertType,
182	                severity: resolvedSeverity,
183	                source: resolvedSource,
184	                confidence: parseConfidence(confidence),
185	                snapshot_url: cleanText(snapshot_url || snapshot_path, 500),
186	                device_id: cleanText(device_id, 100),
187	                occurred_at: parseOccurredAt(timestamp || occurred_at),
188	                ...links
189	            }, { transaction: t });
190	
191	            const incident = await IncidentLog.create({
192	                camera_location: cleanText(camera_location, 255),
193	                status: incidentType,
194	                source: resolvedSource,
195	                severity: resolvedSeverity,
196	                person_name: (person_name && person_name !== 'UNKNOWN') ? cleanText(person_name, 255) : null,
197	                confidence_score: null,
198	                resolutionStatus: 'Active',
199	                notes: zone_name ? `[Object Detection] Zone: ${zone_name}` : ''
200	            }, { transaction: t });
201	
202	            await created.update({ incident_log_id: incident.id }, { transaction: t });
203	            return created;
204	        });
205	
206	        res.status(201).json(alert);
207	    } catch (err) {
208	        res.status(500).json({ error: err.message });
209	    }
210	});
211	
212	const UPDATABLE_FIELDS = ['status', 'severity', 'person_name'];
213	
214	// Finds the incident linked to an alert; returns null (never throws) when the alert
215	// predates incident linking or the incident has since been removed.
216	async function findLinkedIncident(alert, t) {
217	    if (!alert.incident_log_id) return null;
218	    if (!IncidentLog || typeof IncidentLog.findByPk !== 'function') return null;
219	    try {
220	        return await IncidentLog.findByPk(alert.incident_log_id, t ? { transaction: t } : undefined);
221	    } catch {
222	        return null;
223	    }
224	}
225	
226	router.put('/:id', verifyToken, requireRole('FM', 'Staff'), async (req, res) => {
227	    try {
228	        if (!/^\d+$/.test(req.params.id)) return res.sendStatus(404);
229	        const alert = await DetectionAlert.findByPk(req.params.id);
230	        if (!alert) return res.sendStatus(404);
231	
232	        const unsupported = Object.keys(req.body).filter((key) => !UPDATABLE_FIELDS.includes(key));
233	        if (unsupported.length > 0) {
234	            return res.status(400).json({ error: `Unsupported field(s): ${unsupported.join(', ')}. Updatable fields are: ${UPDATABLE_FIELDS.join(', ')}.` });
235	        }
236	        const { status, severity, person_name } = req.body;
237	        if (status && !VALID_STATUSES.includes(status)) {
238	            return res.status(400).json({ error: `status must be one of: ${VALID_STATUSES.join(', ')}.` });
239	        }
240	        if (severity && !SEVERITIES.includes(severity)) {
241	            return res.status(400).json({ error: `severity must be one of: ${SEVERITIES.join(', ')}.` });
242	        }
243	
244	        await withTransaction(async (t) => {
245	            const opts = t ? { transaction: t } : undefined;
246	            await alert.update({
247	                ...(status !== undefined && { status }),
248	                ...(severity !== undefined && { severity }),
249	                ...(person_name !== undefined && { person_name: cleanText(person_name, 255) })
250	            }, opts);
251	
252	            // Mirror the shared fields onto the linked incident so both dashboards agree.
253	            const incident = await findLinkedIncident(alert, t);
254	            if (incident) {
255	                await incident.update({
256	                    ...(status !== undefined && { resolutionStatus: STATUS_TO_RESOLUTION[status] || incident.resolutionStatus }),
257	                    ...(severity !== undefined && { severity }),
258	                    ...(person_name !== undefined && { person_name: cleanText(person_name, 255) })
259	                }, opts);
260	            }
261	        });
262	
263	        res.json(alert);
264	    } catch (err) {
265	        res.status(500).json({ error: err.message });
266	    }
267	});
268	
269	router.delete('/:id', verifyToken, requireRole('FM'), async (req, res) => {
270	    try {
271	        if (!/^\d+$/.test(req.params.id)) return res.sendStatus(404);
272	        const alert = await DetectionAlert.findByPk(req.params.id);
273	        if (!alert) return res.sendStatus(404);
274	
275	        // False-alarm removal: soft-delete the alert (paranoid model keeps the audit row)
276	        // and soft-delete the linked incident the same way the incident dashboard's own
277	        // delete endpoint does, so it stops showing as an active incident.
278	        await withTransaction(async (t) => {
279	            const opts = t ? { transaction: t } : undefined;
280	            const incident = await findLinkedIncident(alert, t);
281	            if (incident) await incident.destroy(opts);
282	            await alert.destroy(opts);
283	        });
284	
285	        res.sendStatus(200);
286	    } catch (err) {
287	        res.status(500).json({ error: err.message });
288	    }
289	});
290	
291	// Purge detection alerts older than 30 days — runs once daily
292	function purgeStaleLogs() {
293	    if (typeof DetectionAlert.destroy !== 'function') return;
294	    const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
295	    DetectionAlert.destroy({
296	        where: { createdAt: { [Op.lt]: cutoff } },
297	        force: true
298	    })
299	    .then(n => { if (n > 0) console.log(`[Purge] Removed ${n} stale detection alerts.`); })
300	    .catch(e => console.error('[Purge] Error:', e));
301	}
302	
303	setInterval(purgeStaleLogs, 24 * 60 * 60 * 1000);
304	// Delay the first run by 20s to let Sequelize finish syncing tables on startup
305	setTimeout(purgeStaleLogs, 20000);
306	
307	module.exports = router;
