30	const displayMetric = (value) => (value === null || value === undefined || value === '' ? 'Unavailable' : value);
31	const formatDateTime = (value) => value
32	  ? new Intl.DateTimeFormat('en-SG', { timeZone: 'Asia/Singapore', dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
33	  : 'Not scheduled';
34	const formatPunctuality = (value) => {
35	  if (value === 'ON_TIME') return 'On Time';
36	  if (value === 'LATE') return 'Late';
37	  return 'No Check-In';
