40	// Real icon component reference (icon={VideocamIcon}), never a derived
41	// three-letter pseudo-icon and never JSX (icon={<VideocamIcon />}). The
42	// visible label carries the meaning, so the icon itself stays aria-hidden.
43	const SummaryCard = ({ icon, label, value, helper, to, tone = 'blue-icon' }) => {
