55	      </div>
56	    </>
57	  );
58	
59	  return to ? (
60	    <Link className="summary-card dashboard-link-card" to={to}>
61	      {content}
62	    </Link>
63	  ) : (
64	    <div className="summary-card">{content}</div>
65	  );
